"""Invoke the actual generic C# class and IEnumerable<T> protocol."""
CORE=r'''
static void CircularCheck7(bool ok,string message){if(!ok)throw new InvalidOperationException(message);}
static List<T> CircularRead7<T>(CircularArray<T> actor,int n){using var iterator=((IEnumerable<T>)actor).GetEnumerator();var result=new List<T>();while(iterator.MoveNext()){CircularCheck7(result.Count<n,"Iterators yield exactly the fixed length");CircularCheck7(iterator.Current is not null,"Preserve nonnull generic elements");result.Add(iterator.Current);}CircularCheck7(result.Count==n&&!iterator.MoveNext(),"Iterators have fixed length and remain exhausted");return result;}
static object CircularTwice7<T>(CircularArray<T> actor,int n){using var first=((IEnumerable<T>)actor).GetEnumerator();using var second=((IEnumerable<T>)actor).GetEnumerator();var left=new List<T>();var right=new List<T>();for(int i=0;i<n;++i){CircularCheck7(first.MoveNext()&&second.MoveNext(),"Independent iterators must not consume each other");CircularCheck7(first.Current is not null&&second.Current is not null,"Preserve nonnull elements");left.Add(first.Current);right.Add(second.Current);}CircularCheck7(!first.MoveNext()&&!second.MoveNext(),"Each iterator finishes at the fixed length");return new[]{left,right};}
static object CircularRun7<T>(JsonElement row){var args=row.GetProperty("arguments");T[] initial=JsonSerializer.Deserialize<T[]>(args[1].GetRawText())!,newValues=JsonSerializer.Deserialize<T[]>(args[4].GetRawText())!;var saved=initial.ToArray();int n=initial.Length;var actor=new CircularArray<T>(initial);Func<int,T> get=actor.Get;Action<int,T> set=actor.Set;Action<int> rotate=actor.Rotate;CircularRead7(actor,n);CircularCheck7(initial.SequenceEqual(saved),"Preserve caller initial values");var results=new List<object?>{null};var operations=args[2];var operands=args[3];for(int i=1;i<operations.GetArrayLength();++i){string operation=operations[i].GetString()!;int operand=operands[i].GetInt32();bool invalid=(operation=="Get"||operation=="Set")&&(operand<0||operand>=n);var before=invalid?CircularRead7(actor,n):null;object? result;try{switch(operation){case "Get":T value=get(operand);CircularCheck7(value is not null,"Preserve generic element type");result=value;break;case "Set":set(operand,newValues[i]);result=null;break;case "Rotate":rotate(operand);result=null;break;case "Iterate":result=CircularRead7(actor,n);break;case "IterateTwice":result=CircularTwice7(actor,n);break;default:throw new InvalidOperationException("Unknown operation");}CircularCheck7(!invalid,"Invalid indices raise an index/range exception");}catch(Exception error)when(error is ArgumentOutOfRangeException or IndexOutOfRangeException){if(!invalid)throw;CircularCheck7(CircularRead7(actor,n).SequenceEqual(before!),"Invalid indexing preserves state");result=new {error="index"};}CircularCheck7(initial.SequenceEqual(saved),"Preserve caller initial values during updates");results.Add(result);}return new {actual=new {results,finalValues=CircularRead7(actor,n)},mutationOk=true};}
static object ExecuteCircular7(JsonElement row)=>row.GetProperty("arguments")[0].GetString()=="number"?CircularRun7<int>(row):CircularRun7<string>(row);
'''
